cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);

const totalOrders = data.length;
const confirmed = data.filter(r => r.Status === 'confirmed');
const cancelled = data.filter(r => r.Status === 'cancelled');
const totalRevenue = confirmed.reduce((s,r) => s + r['Total Paid'], 0);
const cancelledValue = cancelled.reduce((s,r) => s + r['Total Paid'], 0);

// Top customers by confirmed spend
const custSpend = {};
confirmed.forEach(r => { custSpend[r.Customer] = (custSpend[r.Customer]||0) + r['Total Paid']; });
const topCust = Object.entries(custSpend).sort((a,b) => b[1]-a[1]);

// Product frequency
const prodFreq = {};
confirmed.forEach(r => r.Items.split(', ').forEach(i => { prodFreq[i] = (prodFreq[i]||0) + 1; }));
const topProd = Object.entries(prodFreq).sort((a,b) => b[1]-a[1]);

// Date range
const dates = [...new Set(data.map(r => r.Date))].sort();

console.log('=== ORDER SUMMARY ===');
console.log('Date range:', dates.join(' to '));
console.log('Total orders:', totalOrders);
console.log('Confirmed:', confirmed.length, '| Cancelled:', cancelled.length);
console.log('Confirmed revenue: \$' + totalRevenue);
console.log('Cancelled order value: \$' + cancelledValue);
console.log('Avg confirmed order: \$' + (totalRevenue/confirmed.length).toFixed(2));
console.log();
console.log('Top customers (confirmed spend):');
topCust.slice(0,5).forEach(([c,v]) => console.log('  ' + c + ': \$' + v));
console.log();
console.log('Top products (confirmed order frequency):');
topProd.slice(0,5).forEach(([p,c]) => console.log('  ' + p + ': ' + c + ' orders'));
"

#!/usr/bin/env node
/**
 * Send the order summary email via SendGrid.
 *
 * Usage:
 *   SENDGRID_API_KEY=SG.xxx SENDER_EMAIL=you@example.com node send_summary_email.js
 *
 * Optional overrides via env vars:
 *   RECIPIENT_EMAIL  (default: bob@example.com)
 */

const fs = require("fs");
const sgMail = require("@sendgrid/mail");

// --- Config -----------------------------------------------------------
const API_KEY = process.env.SENDGRID_API_KEY;
const FROM = process.env.SENDER_EMAIL;
const TO = process.env.RECIPIENT_EMAIL || "bob@example.com";

if (!API_KEY) {
  console.error("Error: SENDGRID_API_KEY env var is required.");
  process.exit(1);
}
if (!FROM) {
  console.error("Error: SENDER_EMAIL env var is required.");
  process.exit(1);
}

sgMail.setApiKey(API_KEY);

// --- Build email content ---------------------------------------------
const summaryMd = fs.readFileSync(__dirname + "/order_summary_email.md", "utf8");

// Strip the To:/Subject: header lines for the plain-text body
const bodyLines = summaryMd.split("\n").filter(
  (l) => !l.startsWith("To:") && !l.startsWith("Subject:")
);
const plainText = bodyLines.join("\n").trim();

const htmlBody = `
<h2>Order Summary — September 2026</h2>

<h3>Overview</h3>
<ul>
  <li><strong>Date range:</strong> September 2–4, 2026</li>
  <li><strong>Total orders:</strong> 27</li>
  <li><strong>Confirmed:</strong> 24 &nbsp;|&nbsp; <strong>Cancelled:</strong> 3</li>
  <li><strong>Confirmed revenue:</strong> $1,831</li>
  <li><strong>Cancelled order value:</strong> $186</li>
  <li><strong>Average confirmed order value:</strong> $76.29</li>
</ul>

<h3>Top Customers (by confirmed spend)</h3>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;">
  <tr><th>Customer</th><th>Spend</th></tr>
  <tr><td>Maya Chen</td><td>$477</td></tr>
  <tr><td>Evan Parker</td><td>$276</td></tr>
  <tr><td>Alicia Morgan</td><td>$137</td></tr>
  <tr><td>user_2f61840f</td><td>$123</td></tr>
  <tr><td>Sofia Ramirez</td><td>$120</td></tr>
</table>

<h3>Most Popular Products (by confirmed order frequency)</h3>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;">
  <tr><th>Product</th><th>Orders</th></tr>
  <tr><td>LogiTech Wireless Mouse M310</td><td>13</td></tr>
  <tr><td>OXO SoftWorks 3-Piece Mixing Bowl Set</td><td>7</td></tr>
  <tr><td>Everyday Canvas Tote Bag</td><td>5</td></tr>
  <tr><td>Bamboo Desk Organizer Set</td><td>5</td></tr>
  <tr><td>Levi's Classic Cotton T-Shirt</td><td>4</td></tr>
</table>

<h3>Key Takeaways</h3>
<ul>
  <li><strong>Maya Chen</strong> is the top customer, accounting for ~26% of confirmed revenue across 7 confirmed orders.</li>
  <li>The <strong>LogiTech Wireless Mouse M310</strong> appeared in nearly half of all confirmed orders (13 of 24).</li>
  <li>The cancellation rate is relatively low at <strong>11%</strong> (3 of 27 orders).</li>
  <li>Most orders (25 of 27) were placed on Sep 2, with only 2 on Sep 4.</li>
  <li>Product mix spans electronics, kitchen items, apparel, and home goods, with electronics/accessories dominating.</li>
</ul>

<p>Best regards,<br/>Meridian Analytics Platform</p>
`;

// --- Send -------------------------------------------------------------
const msg = {
  to: TO,
  from: FROM,
  subject: "Order Summary — September 2026",
  text: plainText,
  html: htmlBody,
};

sgMail
  .send(msg)
  .then(() => {
    console.log(`✅ Email sent successfully to ${TO}`);
  })
  .catch((err) => {
    console.error("❌ Failed to send email:");
    console.error(err.response ? err.response.body : err.message);
    process.exit(1);
  });
